// src/lib/input/detectNetwork.ts
function detectNetwork(bundle) {
  const haystack = allText(bundle).map((t) => t.text).join("\n").toLowerCase();
  if (!haystack) return null;
  let best = null;
  for (const rule of visibleNetworks()) {
    let score = 0;
    for (const sub of rule.requiredScripts) {
      if (sub && haystack.includes(sub.toLowerCase())) score += sub.length;
    }
    if (score > 0 && (!best || score > best.score)) {
      best = { id: rule.id, score };
    }
  }
  return best?.id ?? null;
}

