// src/validators/size.ts
function sizeValidator(bundle, rule) {
  const limit = rule.sizeLimitBytes;
  const measured = bundle.zippedBytes ?? bundle.totalBytes;
  const label = bundle.zippedBytes != null ? "Zipped" : "Total";
  const evidence2 = bundle.zippedBytes != null ? `${formatBytes(measured)} zipped \xB7 ${formatBytes(bundle.totalBytes)} uncompressed` : `${formatBytes(measured)} uncompressed`;
  if (measured > limit) {
    return [
      {
        id: "size",
        severity: "error",
        title: "Exceeds size limit",
        detail: `${label} weight is ${formatBytes(measured)}, over the ${formatBytes(limit)} limit for ${rule.label}.`,
        suggestion: "Compress images, subset fonts to used glyphs, and drop unused assets to get under the limit.",
        evidence: evidence2
      }
    ];
  }
  if (bundle.zippedBytes != null && bundle.totalBytes > limit) {
    return [
      {
        id: "size",
        severity: "warning",
        title: "Uncompressed load exceeds limit",
        detail: `Packaged at ${formatBytes(measured)} (under ${formatBytes(limit)}), but the uncompressed assets total ${formatBytes(
          bundle.totalBytes
        )}. Networks that measure the uncompressed initial load (e.g. Amazon) may still reject it.`,
        suggestion: "Reduce raw asset weight, not just the zip, to stay safe everywhere.",
        evidence: evidence2
      }
    ];
  }
  return [
    {
      id: "size",
      severity: "pass",
      title: "Within size limit",
      detail: `${label} weight is ${formatBytes(measured)}, under the ${formatBytes(limit)} limit for ${rule.label}.`,
      evidence: evidence2
    }
  ];
}

// src/validators/structure.ts
function structureValidator(bundle, rule) {
  const checks = [];
  if (bundle.entryPath) {
    checks.push({
      id: "entry",
      severity: "pass",
      title: "Entry HTML found",
      detail: `Using "${bundle.entryPath}" as the banner entry point.`
    });
  } else {
    checks.push({
      id: "entry",
      severity: "error",
      title: "No entry HTML",
      detail: "The banner must contain an index.html (or another .html) as its entry point.",
      suggestion: "Add an index.html at the archive root."
    });
  }
  for (const sf of rule.specialFiles) {
    const found = findByName(bundle, sf.name);
    checks.push({
      id: `special-file:${sf.name}`,
      severity: found ? "pass" : sf.required ? "error" : "warning",
      title: found ? `${sf.name} present` : `Missing ${sf.name}`,
      detail: found ? `Required file "${sf.name}" is present.` : `${rule.label} expects a "${sf.name}" file. ${sf.note ?? ""}`.trim(),
      suggestion: found ? void 0 : sf.note
    });
  }
  const nested = bundle.files.filter((f) => extOf(f.path) === "zip");
  if (nested.length > 0) {
    checks.push({
      id: "nested-archive",
      severity: "warning",
      title: "Nested archive detected",
      detail: `The upload contains ${nested.length} inner .zip file(s): ${nested.map((f) => baseName(f.path)).join(", ")}. Networks expect a flat creative, not a zip-of-zips.`,
      suggestion: "Unpack the inner archive and re-zip a single creative."
    });
  }
  for (const [i, w] of bundle.warnings.entries()) {
    if (w.startsWith("No HTML entry")) continue;
    checks.push({
      id: `bundle-warning:${i}`,
      severity: "warning",
      title: "Packaging note",
      detail: w
    });
  }
  return checks;
}

// src/validators/registry.ts
var VALIDATORS = [
  structureValidator,
  sizeValidator,
  animationDurationValidator,
  dimensionsValidator,
  requiredTagsValidator,
  clickTagValidator,
  clickBehaviorValidator,
  externalUrlValidator
];
function worst(checks) {
  if (checks.some((c) => c.severity === "error")) return "error";
  if (checks.some((c) => c.severity === "warning")) return "warning";
  return "pass";
}
function validate(bundle, rule) {
  const checks = VALIDATORS.flatMap((v) => v(bundle, rule));
  return {
    network: rule,
    checks,
    errors: checks.filter((c) => c.severity === "error").length,
    warnings: checks.filter((c) => c.severity === "warning").length,
    infos: checks.filter((c) => c.severity === "info").length,
    passed: checks.filter((c) => c.severity === "pass").length,
    verdict: worst(checks)
  };
}

// src/cli/validate.ts
var USAGE = `Usage: node validate.mjs <banner.zip | banner.html> [options]

Options:
  --network <id>    Validate against one network (see --list-networks)
  --all             Validate against every visible network (compatibility matrix)
  --fix             Auto-fix fixable errors for the chosen network and write a
                    fixed copy: strip non-whitelisted external URLs (Amazon DSP)
                    and/or compress images to fit the size limit. Needs a single
                    network (--network, or an auto-detected one).
  -o, --output <p>  Output path for --fix (default: <input>_fixed.<zip|html>)
  --json            Machine-readable output
  --list-networks   Print known network ids and exit
  -h, --help        Show this help

Default mode (no --network/--all): auto-detect the network from vendor script
markers; falls back to the all-networks matrix when undetectable.

Exit codes: 0 = pass/warnings, 1 = errors, 2 = usage or I/O error.
(Matrix mode exits 1 only when every network reports errors.)`;
